## Results for the final POPULATION HMM that the main script does not write: Table 4, state means, expected stays, in-sample error by state.
suppressPackageStartupMessages({ library(coda); library(data.table) })
set.seed(2026)
proj <- "~/Documents/spatial_anlysis/update_HMM"; out <- file.path(proj, "final_pop", "improve_hmm")
S0 <- readRDS(file.path(proj, "INLA_Rebuilt_From_Zero_OCCPOP.rds")); dat <- as.data.table(S0$data); setorder(dat, ID_area, ID_time)
Z <- 92; T <- 120; Y <- matrix(dat$O, Z, T, byrow = TRUE); Em <- matrix(dat$E, Z, T, byrow = TRUE); OFF <- Em / mean(Em)
zpop <- as.numeric(scale(log(as.numeric(tapply(dat$monthly_population, dat$ID_area, mean)))))
X <- as.matrix(readRDS(file.path(out, "cache_tau2_2_hi170_pop_rmin0.5_hm_main_n100000_b200000.rds")))
stn <- c("Baseline", "Moderate", "High-intensity")
t4 <- rbindlist(lapply(1:3, function(i) rbindlist(lapply(1:3, function(j) { v <- rowMeans(X[, sprintf("gam[%d,%d,%d]", 1:Z, i, j)])
  data.table(from = stn[i], to = stn[j], mean = mean(v), lo = quantile(v, .025), hi = quantile(v, .975)) }))))
fwrite(t4, file.path(out, "Table_4_transition_matrix_pop_FINAL.csv")); t4[, txt := sprintf("%.3f [%.3f, %.3f]", mean, lo, hi)]
cat("TABLE 4 (population model)\n"); print(dcast(t4, from ~ to, value.var = "txt")[match(stn, from), c("from", stn), with = FALSE], row.names = FALSE)
cat("\nState means (zone-month of average expected count and average population) and expected stay\n")
st <- rbindlist(lapply(1:3, function(s) { m <- rowMeans(X[, sprintf("mu[%d,%d]", 1:Z, s)]); p <- rowMeans(X[, sprintf("gam[%d,%d,%d]", 1:Z, s, s)]); d <- 1 / (1 - p)
  data.table(state = stn[s], mean = mean(m), mean_lo = quantile(m, .025), mean_hi = quantile(m, .975), self = mean(p), stay = mean(d), stay_lo = quantile(d, .025), stay_hi = quantile(d, .975)) }))
print(st[, lapply(.SD, function(x) if (is.numeric(x)) round(x, 3) else x)], row.names = FALSE); fwrite(st, file.path(out, "Table_S_state_means_and_stays_pop_FINAL.csv"))
cat(sprintf("\nPopulation effect b_pop: %.3f (95%% CrI %.3f to %.3f)\n", mean(X[, "b_pop"]), quantile(X[, "b_pop"], .025), quantile(X[, "b_pop"], .975)))
kk <- sample(nrow(X), 1000); scol <- sprintf("S[%d,%d]", rep(1:Z, T), rep(1:T, each = Z))
mcol <- sprintf("mu[%d,%d]", rep(1:Z, 3), rep(1:3, each = Z)); dcol <- sprintf("delta[%d,%d]", rep(1:Z, 3), rep(1:3, each = Z))
LAM <- matrix(0, Z, T); CNT <- array(0, c(Z, T, 3))
for (k in kk) { A <- matrix(X[k, scol], Z, T); ls <- matrix(X[k, mcol] * exp(X[k, dcol]), Z, 3)
  LAM <- LAM + matrix(ls[cbind(rep(1:Z, T), as.vector(A))], Z, T) * OFF * exp(X[k, "b_pop"] * zpop) / length(kk)
  for (s in 1:3) CNT[, , s] <- CNT[, , s] + (A == s) }
modal <- apply(CNT, c(1, 2), which.max)
rw <- function(lab, i) data.table(state = lab, n = sum(i), observed_mean = mean(Y[i]), predicted_mean = mean(LAM[i]), MAE = mean(abs(Y[i] - LAM[i])), RMSE = sqrt(mean((Y[i] - LAM[i])^2)), bias = mean(LAM[i] - Y[i]))
tab <- rbind(rbindlist(lapply(1:3, function(s) rw(stn[s], modal == s))), rw("All zone-months", modal > 0)); tab[, (3:7) := lapply(.SD, round, 2), .SDcols = 3:7]
cat("\nIn-sample error by state (population model)\n"); print(tab, row.names = FALSE)
cat(sprintf("Total predicted %.0f vs observed %d cases\n", sum(LAM), sum(Y))); fwrite(tab, file.path(out, "Table_S_HMM_error_by_state_pop_FINAL.csv"))
